using RSSG.Core; using System.Text.Json;
static void Assert(bool x,string m){if(!x)throw new Exception("TEST FAILED: "+m);}
var g=new StarSystemGenerator();var s=GenerationSettings.Default with{Seed=24680,MinPlanets=5,MaxPlanets=5,MinMoonsPerPlanet=1,MaxMoonsPerPlanet=2,MinAsteroidBelts=1,MaxAsteroidBelts=1};var a=g.Generate(s);var b=g.Generate(s);Assert(a.Name==b.Name,"stable name");Assert(a.Stars.SequenceEqual(b.Stars),"stable stars");Assert(JsonSerializer.Serialize(a.Planets)==JsonSerializer.Serialize(b.Planets),"stable planets");Assert(a.Planets.Count==5,"planet count");Assert(a.Planets.All(p=>p.Moons.Count is >=1 and <=2),"moon range");Assert(a.AsteroidBelts.Count==1,"belt count");bool bad=false;try{g.Generate(s with{MinPlanets=9,MaxPlanets=2});}catch(ArgumentOutOfRangeException){bad=true;}Assert(bad,"validation");Console.WriteLine("RSSG core smoke tests passed.");